/** Payslip CRUD — shared config (read-mostly; rows are generated by payroll runs). */
import { defineCrud } from '@/lib/crud'

export const payslipsCrud = defineCrud({
  model: 'payslip',
  module: 'hr',
  filterFields: ['payrollRunId', 'employeeId', 'status'],
  defaultSort: { field: 'netPay', dir: 'desc' },
})
